    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price (AC-2)
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price (AC-3)
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  # NEEDS DECISION (AC-4): the title says the reduction lands on a whole cent "in the customer's
  # favour", yet the expected charge is 7 cents, i.e. no reduction on a 0.35 cent reduction.
  # Rounding in the customer's favour would charge 6 cents. Values below are verbatim from ac.md;
  # do not implement until DISCUSS confirms which statement is right.
  @edge-case @needs-decision
  Scenario: Bronze customer with a tiny basket is charged the AC-4 amount (AC-4)
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents

  # NOT DECIDED: Platinum tier. The business has not agreed a reduction, so there is
  # deliberately NO scenario, NO expected value and NO test. Do not guess one.
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public sealed class LoyaltyDiscountAcceptanceTests
{
    [Theory]
    // Bronze customer is charged the Bronze price (AC-1)
    [InlineData(LoyaltyTier.Bronze, 10000, 9500)]
    public void Returning_customer_is_charged_the_price_of_their_loyalty_tier(
        LoyaltyTier loyaltyTier, int subtotalCents, int expectedChargedCents)
    {
        var quote = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, loyaltyTier));

        Assert.Equal(expectedChargedCents, quote.TotalCents);
    }
}
EOF
